#include <bits/stdc++.h>

using namespace std;

using ll = long long;

bool chmin(ll &a, ll b) {
    if (a > b) {
        a = b;
        return true;
    }
    return false;
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    --k;
    vector<vector<pair<int, int>>> G(n);
    for (int i = 0; i < m; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        --a, --b;
        G[a].emplace_back(b, c);
        G[b].emplace_back(a, c);
    }
    vector dp(1 << k, vector<ll>(n, 1e18));
    for (int i = 0; i < k; i++) dp[1 << i][i] = 0;
    for (int bit = 1; bit < (1 << k); bit++) {
        for (int sub = bit; sub > 0; sub = (sub - 1) & bit) {
            for (int i = 0; i < n; i++) {
                chmin(dp[bit][i], dp[sub][i] + dp[bit - sub][i]);
            }
        }
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
        for (int i = 0; i < n; i++) pq.emplace(dp[bit][i], i);
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d > dp[bit][u]) continue;
            for (auto [v, l]: G[u]) {
                if (chmin(dp[bit][v], d + l)) {
                    pq.emplace(d + l, v);
                }
            }
        }
    }
    for (int i = k; i < n; i++) {
        cout << dp.back()[i] << '\n';
    }
}
